// Chapter 23 of the book — converted from the HTML edition; generated file.

export const n = 23;
export const num = "23";
export const title = "Rebase تعاملی — بازنویسی تاریخچه مثل مجسمه‌ساز";
export const label = "فصل ۲۳ · Rebase تعاملی";
export const part = 2;
export const html = "<p class=\"lead\">Rebase کامیت‌های شاخهٔ تو را برمی‌دارد و یکی‌یکی روی نوک یک شاخهٔ دیگر دوباره اعمال می‌کند. نتیجه تاریخچهٔ خطی است، ولی هش هر کامیت عوض می‌شود. فقط روی شاخه‌ای که دیگران از آن استفاده نمی‌کنند این کار را بکن.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>rebase را به‌عنوان «کامیت‌ها را روی پایهٔ جدید دوباره پخش کن» توضیح دهی</li>\n<li><code>rebase -i</code> را برای squash و reword به کار ببری</li>\n<li><code>--autosquash</code> و <code>fixup!</code> را بلد باشی</li>\n<li class=\"keep-next\">قانون طلایی را هرگز نشکنی</li>\n</ul>\n<div class=\"diagram\">\n<img src=\"/book/figures/merge-rebase.svg\" alt=\"merge در برابر rebase\"/>\n<p class=\"figcap\">شکل ۱۶ — rebase کامیت‌های جدید می‌سازد (D′ و E′)؛ هش عوض می‌شود.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧠 rebase دقیقاً چه می‌کند؟</span></span></h2>\n<p class=\"keep-next\">Git هر کامیت شاخهٔ تو را که در <code>main</code> نیست برمی‌دارد، <code>main</code> را HEAD می‌کند، و وصله‌ها را یکی‌یکی اعمال می‌کند. نتیجه: تاریخچهٔ خطی. هزینه: هویت جدید برای هر کامیت.</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">به‌روز کردن شاخهٔ شخصی</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>fetch<span style=\"color: #F8F8F2\"> </span>origin\ngit<span style=\"color: #F8F8F2\"> </span>switch<span style=\"color: #F8F8F2\"> </span>feat/auth\ngit<span style=\"color: #F8F8F2\"> </span>rebase<span style=\"color: #F8F8F2\"> </span>origin/main\ngit<span style=\"color: #F8F8F2\"> </span>push<span style=\"color: #F8F8F2\"> </span>--force-with-lease\n</pre></div>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"col-title\">🖥️ VS Code Git</div>\n<ul>\n<li><code>...</code> → <strong>Pull (Rebase)</strong> برای به‌روز کردن شاخه</li>\n<li>Palette: <code>Git: Rebase Branch...</code> → <code>origin/main</code></li>\n<li>تعارض: Merge Editor → Stage → <code>Git: Rebase Continue</code></li>\n<li>نوار زرد بالای ادیتور یعنی rebase ناتمام است — کامیت عادی نزن</li>\n<li><code>Git: Rebase Abort</code> برای پشیمانی</li>\n</ul>\n</div>\n<div class=\"col\"><div class=\"col-title\">⌨️ Terminal</div>\n<p><code>git fetch origin</code>\n<code>git rebase origin/main</code>\n<code>git rebase --continue</code>\n<code>git rebase --abort</code>\n<code>git push --force-with-lease</code></p>\n</div>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🎛️ interactive — اتاق عمل</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">پنج کامیت آخر را ویرایش کن</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>rebase<span style=\"color: #F8F8F2\"> </span>-i<span style=\"color: #F8F8F2\"> </span>HEAD~5\n</pre></div>\n<p class=\"keep-next\">ویرایشگر (در این کتاب VS Code با <code>core.editor=&quot;code --wait&quot;</code>) لیستی می‌آورد:</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">todo</span></div><pre>pick a11 feat: add login form\npick b22 fix: typo in label\npick c33 wip\npick d44 feat: wire submit\npick e55 docs: readme\n</pre></div>\n<p class=\"keep-next\">فرمان‌ها:</p>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>فرمان</th>\n<th>معنی</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>pick</code></td>\n<td>نگه دار</td>\n</tr>\n<tr>\n<td><code>reword</code></td>\n<td>پیام را عوض کن</td>\n</tr>\n<tr>\n<td><code>edit</code></td>\n<td>بایست؛ فایل را درست کن</td>\n</tr>\n<tr>\n<td><code>squash</code></td>\n<td>با قبلی یکی کن؛ پیام‌ها را ترکیب کن</td>\n</tr>\n<tr>\n<td><code>fixup</code></td>\n<td>با قبلی یکی کن؛ پیام را دور بریز</td>\n</tr>\n<tr>\n<td><code>drop</code></td>\n<td>حذف</td>\n</tr>\n</tbody>\n</table></div><p>ترتیب خطوط = ترتیب تاریخچه. جابه‌جا کن تا داستان منطقی شود.</p>\n<div class=\"callout callout-danger\"><div class=\"callout-title\">هرگز rebase روی کامیت عمومی</div>\n<p>اگر <code>origin/main</code> یا شاخه‌ای که همکارت checkout کرده شامل آن هش‌هاست، rebase = دو تاریخچهٔ موازی و force-push جنگی.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">⚡ fixup و autosquash</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">بعد از ریویو، بدون کامیت «address comments»</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>commit<span style=\"color: #F8F8F2\"> </span>--fixup<span style=\"color: #F8F8F2\"> </span>a11\ngit<span style=\"color: #F8F8F2\"> </span>rebase<span style=\"color: #F8F8F2\"> </span>-i<span style=\"color: #F8F8F2\"> </span>--autosquash<span style=\"color: #F8F8F2\"> </span>origin/main\n</pre></div>\n<p><code>--fixup</code> پیامی مثل <code>fixup! feat: add login form</code> می‌سازد؛ autosquash آن را زیر هدف می‌چسباند. در Git جدید <code>git commit --squash</code> هم هست.</p>\n<p>از Git ۲.۳۸+ پرچم <code>--update-refs</code> شاخه‌های محلی دیگری که به کامیت‌های بازنویسی‌شده اشاره می‌کردند را هم حرکت می‌دهد — نجات از شاخه‌های یتیم.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧩 تعارض وسط rebase</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">نجات</span></div><pre><span style=\"color: #959077\"># فایل را در VS Code حل و Stage کن</span>\ngit<span style=\"color: #F8F8F2\"> </span>rebase<span style=\"color: #F8F8F2\"> </span>--continue\ngit<span style=\"color: #F8F8F2\"> </span>rebase<span style=\"color: #F8F8F2\"> </span>--abort<span style=\"color: #F8F8F2\">          </span><span style=\"color: #959077\"># پشیمانی کامل</span>\ngit<span style=\"color: #F8F8F2\"> </span>rebase<span style=\"color: #F8F8F2\"> </span>--skip<span style=\"color: #F8F8F2\">           </span><span style=\"color: #959077\"># این وصله را دور بینداز — خطرناک</span>\n</pre></div>\n<p><code>rerere</code> (فصل ۲۴) تعارض تکراری را به خاطر می‌سپارد.</p>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">VS Code</div>\n<p>وضعیت rebase را نوار زرد بالای ادیتور نشان می‌دهد. Merge Editor همان UI تعارض فصل ۷ است. تا نوار زرد هست، کامیت عادی نزن.</p>\n</div>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Mid — چرا PR بعد از rebase «جدید» به نظر می‌رسد؟</strong> چون هش عوض شده؛ GitHub فایل‌ها را مقایسه می‌کند نه هش را. Force-with-lease لازم است.</p>\n<p><strong>Senior — rebase در برابر merge برای به‌روز کردن شاخه؟</strong> rebase تاریخچهٔ PR را خطی و خوانا می‌کند؛ merge یک گره همگام‌سازی اضافه می‌کند. تیم باید یکی را انتخاب کند.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>rebase فقط روی شاخهٔ خودت</li>\n<li><code>fixup</code> + autosquash را بلدی</li>\n<li><code>--abort</code> عضله‌ای شده</li>\n<li>force خام نمی‌زنی</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> cherry-pick، revert پیشرفته و rerere.</p></div>";
export default { n, num, title, label, part, html };
